# Script code that specifies how to create a custom neck.
#
# The script needs to set a dictionary "result" with keys:
# module_class    - a subclass of nn.Module or detectron2.modeling.Backbone
# module_kwargs   - keyword arguments used to instantiate the neck
#
# Tip:
# Use torch.nn.Module if:
#   - The neck is a simple intermediate layer not intended to be a standalone feature extractor.
#   - You are wrapping a pre-existing PyTorch block that doesn't need detectron2-specific metadata.
# Use detectron2.modeling.Backbone if:
#   - You want to utilize Detectron2's registry and specialized methods like .output_shape().
#   - The neck is the final feature provider for the ROI Heads/Proposal Generator.
#   - You need to define size_divisibility or padding_constraints for the entire model.

import torch
import torch.nn as nn
import torch.nn.functional as F

from detectron2.layers import ShapeSpec, Conv2d


class CustomNeck(nn.Module):
    def __init__(self, bottom_up, input_shapes, output_channels, **kwargs):
        super().__init__()
        self.bottom_up = bottom_up

        self.in_features = sorted(list(input_shapes.keys()), reverse=True)
        self._input_shapes = input_shapes
        self._output_channels = output_channels

        self.lateral_convs = nn.ModuleDict()
        self.output_convs = nn.ModuleDict()

        for name in self.in_features:
            in_channels = input_shapes[name].channels
            self.lateral_convs[name] = Conv2d(in_channels, output_channels, kernel_size=1)
            self.output_convs[name] = Conv2d(output_channels, output_channels, kernel_size=3, padding=1)

    def forward(self, x):
        bottom_up_features = self.bottom_up(x)
        results = {}
        prev_features = None

        for name in self.in_features:
            out_name = name.replace("res", "p").replace("stage", "p")
            lateral_feat = self.lateral_convs[name](bottom_up_features[name])

            if prev_features is not None:
                top_down_feat = F.interpolate(prev_features, scale_factor=2.0, mode="nearest")
                current_feat = lateral_feat + top_down_feat
            else:
                current_feat = lateral_feat

            results[out_name] = self.output_convs[name](current_feat)
            prev_features = current_feat

        return results

    def output_shape(self):
        return {
            name.replace("res", "p").replace("stage", "p"): ShapeSpec(
                channels=self._output_channels, 
                stride=self._input_shapes[name].stride
            ) for name in self.in_features
        }

    @property
    def size_divisibility(self):
        return getattr(self.bottom_up, "size_divisibility", 32)

    @property
    def padding_constraints(self):
        return getattr(self.bottom_up, "padding_constraints", {})


result = {
    "module_class": CustomNeck,
    "module_kwargs": {
        "output_channels": 256
    }
